result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/mergecfg.py", "content": "#!/usr/bin/env python3
"""Layered YAML config merger.

Usage: python3 mergecfg.py base.yaml [overlay1.yaml [overlay2.yaml ...]]

Semantics:
  - Maps are deep-merged; later files win on conflicts.
  - Lists are REPLACED by default.
  - A list whose first element is the literal string '<<append>>'
    appends the remaining elements to the base list instead of replacing it.
  - An explicit null value in an overlay DELETES that key from the result.

Output: final merged YAML on stdout, keys sorted.
"""

import sys
from typing import Any

import yaml

APPEND_MARKER = "<<append>>"


def deep_merge(base: Any, overlay: Any) -> Any:
    """Merge overlay onto base, returning a new structure."""
    # Explicit null in overlay => delete this key (caller handles removal).
    if overlay is None and base is not None:
        return _DELETE

    if isinstance(base, dict) and isinstance(overlay, dict):
        result = dict(base)
        for key, oval in overlay.items():
            if oval is None and key in result:
                del result[key]  # delete marker
            elif key in result:
                merged = deep_merge(result[key], oval)
                if merged is _DELETE:
                    del result[key]
                else:
                    result[key] = merged
            else:
                # New key: strip a leading append marker if present.
                result[key] = _strip_append(oval)[0]
        return result

    if isinstance(base, list) and isinstance(overlay, list):
        stripped, is_append = _strip_append(overlay)
        if is_append:
            return list(base) + stripped
        return stripped  # replace

    return overlay  # scalars: later wins


# Sentinel used internally to signal deletion through deep_merge's return.
class _DeleteType:
    def __repr__(self) -> str:  # pragma: no cover
        return "<DELETE>"


_DELETE = _DeleteType()


def _strip_append(lst: list) -> tuple[list, bool]:
    """Return (elements_without_marker, had_marker)."""
    if lst and lst[0] == APPEND_MARKER:
        return lst[1:], True
    return lst, False


def main(argv: list[str]) -> int:
    if len(argv) < 2:
        print(f"usage: {argv[0]} base.yaml [overlay.yaml ...]", file=sys.stderr)
        return 2

    merged: Any = {}
    for path in argv[1:]:
        with open(path) as fh:
            doc = yaml.safe_load(fh)
        if doc is None:
            doc = {}
        merged = deep_merge(merged, doc)

    print(yaml.safe_dump(merged, sort_keys=True, default_flow_style=False))
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
