import subprocess
import sys
from pathlib import Path

import yaml

from mergecfg import deep_merge

HERE = Path(__file__).parent


def _load(name: str):
    with open(HERE / name) as fh:
        return yaml.safe_load(fh)


def run_merger(*files: str) -> dict:
    proc = subprocess.run(
        [sys.executable, str(HERE / "mergecfg.py"), *(str(HERE / f) for f in files)],
        capture_output=True,
        text=True,
    )
    assert proc.returncode == 0, proc.stderr
    return yaml.safe_load(proc.stdout)


def load(*files: str) -> dict:
    merged = {}
    for f in files:
        doc = _load(f) or {}
        merged = deep_merge(merged, doc)
    return merged


def test_base_plus_staging():
    result = load("base.yaml", "staging.yaml")
    # nested map merge: staging overrides some leaves, keeps others
    assert result["app"]["name"] == "service-core"
    assert result["app"]["logging"]["level"] == "DEBUG"          # scalar wins
    assert result["app"]["logging"]["handlers"] == ["console", "syslog"]  # replaced
    assert result["app"]["resources"]["limits"]["cpu"] == "2"    # preserved from base
    assert result["features"]["auth"]["enabled"] is False        # overridden
    assert result["features"]["auth"]["providers"] == ["local"]  # untouched by staging
    assert result["features"]["cache"] == {"ttl": 600, "eviction": "lru"}  # new subtree
    # append marker on a key absent from base -> just the remaining elements
    assert result["extra_env"] == ["STAGING_TOKEN=xyz"]
    # base-only keys survive
    assert result["legacy"] == {"mode": "compat"}
    assert set(result.keys()) == {
        "app", "features", "extra_env", "legacy",
    }


def test_base_plus_staging_plus_prod():
    result = load("base.yaml", "staging.yaml", "prod.yaml")

    # list append: prod appends fluentd to staging's handlers
    assert result["app"]["logging"]["handlers"] == [
        "console", "syslog", "fluentd",
    ]
    # scalar override chain: INFO -> DEBUG -> (prod doesn't touch level)
    assert result["app"]["logging"]["level"] == "DEBUG"
    # deepest map merge keeps cpu, overrides memory
    assert result["app"]["resources"]["limits"] == {"cpu": "2", "memory": "4Gi"}

    assert result["features"]["auth"]["enabled"] is False
    # append to base's provider list through two overlays
    assert result["features"]["auth"]["providers"] == ["local", "oidc"]
    # explicit null deletes features.cache.ttl; eviction remains
    assert result["features"]["cache"] == {"eviction": "lru"}
    # explicit null at top level deletes the whole legacy section
    assert "legacy" not in result
    # brand-new top-level section from prod
    assert result["retries"] == {"max_attempts": 5}
    assert result["extra_env"] == ["STAGING_TOKEN=xyz"]

    assert set(result.keys()) == {"app", "features", "extra_env", "retries"}


def test_cli_output_matches_library_and_is_sorted():
    expected = load("base.yaml", "staging.yaml", "prod.yaml")
    actual = run_merger("base.yaml", "staging.yaml", "prod.yaml")
    assert actual == expected

    proc = subprocess.run(
        [sys.executable, str(HERE / "mergecfg.py"),
         str(HERE / "base.yaml")],
        capture_output=True,
        text=True,
    )
    lines = [ln for ln in proc.stdout.splitlines() if ln and not ln.startswith(" ")][:1]
    assert lines == ["app:"]  # top-level keys sorted: app comes first


def test_append_marker_only_counts_as_first_element():
    base = {"items": [1, 2]}
    overlay = {"items": ["<<append>>", 3]}
    assert deep_merge(base, overlay) == {"items": [1, 2, 3]}


def test_plain_list_replaces_even_if_base_has_marker_free_list():
    base = {"items": [1, 2, 3]}
    overlay = {"items": [9]}
    assert deep_merge(base, overlay) == {"items": [9]}
